public class ProductStack {
    private static class Node {
        long value;
        long product;  // product of all elements from bottom to this node
        Node next;

        Node(long value, long product) {
            this.value = value;
            this.product = product;
        }
    }

    private Node top;
    private int size;

    public ProductStack() {
        this.top = null;
        this.size = 0;
    }

    /**
     * Push value onto stack. O(1).
     */
    public void push(long value) {
        long newProduct;
        if (top == null) {
            newProduct = value;
        } else {
            newProduct = top.product * value;
        }
        top = new Node(value, newProduct);
        size++;
    }

    /**
     * Pop from stack. O(1).
     * @return the popped value
     * @throws EmptyStackException if stack is empty
     */
    public long pop() {
        if (top == null) {
            throw new java.util.EmptyStackException();
        }
        long value = top.value;
        top = top.next;
        size--;
        return value;
    }

    /**
     * Query: get running product of all elements in stack. O(1).
     * Returns the product from bottom to top.
     * @return product of all elements (1 if empty)
     */
    public long getProduct() {
        return (top == null) ? 1L : top.product;
    }

    public int size() {
        return size;
    }

    public boolean isEmpty() {
        return size == 0;
    }

    // Quick test
    public static void main(String[] args) {
        ProductStack stack = new ProductStack();
        stack.push(2);
        System.out.println("After push(2): product = " + stack.getProduct());  // 2

        stack.push(3);
        System.out.println("After push(3): product = " + stack.getProduct());  // 6

        stack.push(5);
        System.out.println("After push(5): product = " + stack.getProduct());  // 30

        long popped = stack.pop();
        System.out.println("Popped: " + popped + ", product = " + stack.getProduct());  // 6

        stack.push(-2);
        System.out.println("After push(-2): product = " + stack.getProduct());  // -12
    }
}
