public class ProductStack {
    private static class Node {
        int value;
        long productUpToHere;  // Product of all elements from bottom to this node

        Node(int value, long productUpToHere) {
            this.value = value;
            this.productUpToHere = productUpToHere;
        }
    }

    private Node top;

    /**
     * Push a value onto the stack in O(1).
     * Updates the running product.
     */
    public void push(int value) {
        long newProduct = (top == null) ? value : (top.productUpToHere * (long) value);
        top = new Node(value, newProduct);
    }

    /**
     * Pop from the stack in O(1).
     */
    public int pop() {
        if (top == null) {
            throw new IllegalStateException("Stack is empty");
        }
        int value = top.value;
        top = top.next;
        return value;
    }

    /**
     * Return the product of all elements currently in the stack in O(1).
     * Returns 1 if the stack is empty.
     */
    public long getProduct() {
        return top == null ? 1L : top.productUpToHere;
    }

    public boolean isEmpty() {
        return top == null;
    }
}
```

